from lib import *
r=[]
r.append(R(6531377,"कोरियन बीबीक्यू से प्रेरित बेक्ड सैल्मन",
"इस सैल्मन पर लगे कोरियन बीबीक्यू से प्रेरित सॉस में मीठे, नमकीन, खट्टे और तीखे स्वाद का आदर्श संतुलन है। मिठास प्राकृतिक रूप से फलों से आती है, अलग से डाली गई चीनी से नहीं। आप इस सॉस को चिकन पर भी इस्तेमाल कर सकते हैं: बिना हड्डी और बिना त्वचा वाली चिकन जाँघों को सॉस के बिना 15 मिनट बेक करें, फिर उन पर सॉस लगाएँ और 15 मिनट और, या पूरी तरह पकने तक बेक करें।",
"4","1 फ़िले",
["4 (6 औंस के) बीच के हिस्से के त्वचा सहित सॉकआई सैल्मन फ़िले","2 बड़े चम्मच बिना चीनी मिलाया केचप","1 बड़ा चम्मच फलों की मिठास वाला खुबानी का जैम","1 बड़ा चम्मच कम सोडियम वाला तामारी या सोया सॉस","2 छोटे चम्मच चावल का सिरका","1/4 छोटा चम्मच हॉट सॉस","1 छोटा चम्मच तिल"],
["ओवन को 400° F पर पहले से गरम करें। एक बड़ी किनारेदार बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","सैल्मन को त्वचा वाला हिस्सा नीचे की ओर रखकर बेकिंग शीट पर रखें।","एक छोटे कटोरे में केचप, जैम, तामारी, सिरका और तीखी मिर्च का सॉस मिलाएँ। चम्मच के पिछले हिस्से से इस मिश्रण को हर फ़िले के ऊपर हल्के से फैलाएँ। ऊपर से तिल छिड़कें।","सैल्मन के परतदार होने और पूरी तरह पकने तक (अंदर का तापमान कम से कम 145°F हो), लगभग 16 मिनट बेक करें। परोसें।"]))
r.append(R(6536371,"पालक, ग्रेप टमाटर और भुने हुए लाल आलू के साथ झींगा सॉते",
"यह तेज़ और स्वादिष्ट झींगा व्यंजन कम कार्ब और कम चर्बी वाले भोजन पैटर्न का पालन करता है, यानी यह उन लोगों के लिए अच्छा विकल्प है जो अपने रक्तचाप का ध्यान रखते हैं। रसीले झींगों को ताज़े पालक, मीठे ग्रेप टमाटर और कुरकुरे भुने हुए लाल आलू के साथ भूना जाता है, जिससे स्वादों और बनावट का सामंजस्यपूर्ण मेल बनता है। यह एक भरपेट और स्वादिष्ट व्यंजन है जो हफ़्ते के दिनों के रात के खाने के लिए एकदम सही है।",
"4","1 कप झींगे और सब्ज़ियाँ, ½ कप आलू",
["16 औंस बेबी लाल आलू","1 बड़ा चम्मच जैतून का तेल","1/2 छोटा चम्मच इटैलियन सीज़निंग","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 पिंट ग्रेप टमाटर (आधे कटे हुए)","2 कली लहसुन (बारीक कटी हुई)","1 1/2 पाउंड बड़े झींगे (छिले और नस निकाले हुए)","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ़्लेक्स","5 औंस बेबी पालक","1 1/2 औंस पारमेज़न चीज़ (बारीक कसा हुआ)","1/2 कप ताज़ी तुलसी की पत्तियाँ (पतली लंबी कतरों में कटी हुई)"],
["ओवन को 425 डिग्री F पर पहले से गरम करें। बेबी लाल आलू को आकार के अनुसार आधा या चार टुकड़ों में काटें। उन्हें बेकिंग शीट पर 2 छोटे चम्मच जैतून का तेल, इटैलियन सीज़निंग, नमक और काली मिर्च के साथ मिलाएँ।","ओवन में 20–25 मिनट तक भूनें, बीच में एक बार पलटें, जब तक वे सुनहरे और नरम न हो जाएँ।","एक कड़ाही को मध्यम आँच पर गरम करें। कड़ाही में बचा हुआ जैतून का तेल और ग्रेप टमाटर डालें। बीच-बीच में चलाते हुए 3–4 मिनट पकाएँ, या जब तक टमाटर नरम न हो जाएँ और थोड़ा रस न छोड़ दें।","कड़ाही में लहसुन, झींगे और कुटी हुई लाल मिर्च डालें। झींगों को हर तरफ़ 1–2 मिनट भूनें, या जब तक वे अपारदर्शी होकर पूरी तरह पक न जाएँ।","पालक को मुट्ठी-मुट्ठी करके कड़ाही में डालें और हर बार डालने के बाद चलाएँ ताकि वह गल जाए।","आँच को धीमा करें और कड़ाही की सामग्री पर आधा कसा हुआ पारमेज़न चीज़ छिड़कें। मिलाने के लिए चलाएँ और चीज़ को थोड़ा पिघलने दें।","झींगे, भुनी हुई सब्ज़ियाँ और पालक को प्लेटों में बाँटें। बचे हुए पारमेज़न चीज़ और तुलसी की कतरों से सजाएँ। भुने हुए लाल आलू के साथ परोसें।"]))
r.append(R(6536789,"ब्रोकली प्याज़ लैटकेस",
"कम कार्ब वाले ये लैटकेस पारंपरिक आलू की जगह ब्रोकली का उपयोग करते हैं। इनमें पोटैशियम भी कम होता है, जिससे ये किडनी की सेहत के लिए कम पोटैशियम वाला आहार लेने वालों के लिए एक बढ़िया विकल्प हैं।",
"4","1 लैटके",
["3 कप ताज़े या जमे हुए कटे ब्रोकली के फूल","1/2 कप टुकड़ों में कटा प्याज़","2 साबुत अंडे","2 बड़े चम्मच मैदा (ऑल-पर्पज़ आटा)","2 बड़े चम्मच जैतून का तेल"],
["कटी हुई ब्रोकली को थोड़े से पानी में 5 मिनट उबालें, फिर अच्छी तरह पानी निथार दें।","अंडों को एक मध्यम कटोरे में तोड़कर फेंटें। आटा डालकर अच्छी तरह मिलाएँ। ब्रोकली और प्याज़ डालें और आटे-अंडे के मिश्रण में अच्छी तरह मिलने तक चलाएँ।","एक फ्राइंग पैन में मध्यम-तेज़ आँच पर जैतून का तेल गरम करें। मिश्रण को चम्मच से गरम तेल में डालें और 4 बराबर भाग बनाएँ। स्पैचुला से चपटा करें और दोनों तरफ़ सुनहरा भूरा होने तक पकाएँ (हर तरफ़ लगभग 3-4 मिनट)।","लैटकेस को पैन से निकालें और अतिरिक्त तेल सोखने के लिए पेपर टॉवल पर रखें। गरम परोसें।"]))
r.append(R(6536966,"बेसन चीला",
"बेसन और रंग-बिरंगी सब्ज़ियों से बना बेसन चीला कई भारतीय घरों में पसंद किया जाने वाला लोकप्रिय नमकीन पैनकेक है। इसका हल्का मेवे जैसा स्वाद, कुरकुरे किनारे और मुलायम बीच का हिस्सा इसे एक स्वादिष्ट स्नैक या हल्का भोजन बनाते हैं, जबकि बेसन प्रोटीन और फ़ाइबर देता है।",
"1","1 पैनकेक",
["1/4 कप बेसन (चने का आटा)","1/4 कप पानी","2 बड़े चम्मच पीला प्याज़ (बारीक कटा हुआ)","2 बड़े चम्मच पालक (बारीक कटा हुआ)","2 बड़े चम्मच शिमला मिर्च (बारीक कटी हुई)","2 बड़े चम्मच तोरी (कद्दूकस की हुई)","1/4 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच पिसा धनिया","1/16 छोटा चम्मच हल्दी","1/16 छोटा चम्मच चिली पाउडर","1/16 छोटा चम्मच नमक","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच सादा फ़ैट-फ़्री ग्रीक योगर्ट"],
["एक कटोरे में बेसन, पानी और मसालों को चिकना होने तक फेंटकर मिलाएँ।","सब्ज़ियाँ डालकर मिलाएँ। ढककर 5-10 मिनट के लिए अलग रख दें। फिर से अच्छी तरह मिलाएँ।","एक नॉनस्टिक कड़ाही को मध्यम आँच पर गरम करें और उस पर कुकिंग स्प्रे की हल्की परत लगाएँ।","घोल को कड़ाही में डालें, उसे धीरे से बराबर फैलाएँ और आकार को गोल करके 6 इंच का पतला पैनकेक बनाएँ।","हर तरफ़ 2-3 मिनट पकाएँ, जब तक वह हल्का भूरा होकर पूरी तरह पक न जाए।","साथ में डुबोने के लिए 1 बड़ा चम्मच सादा ग्रीक योगर्ट रखकर गरमागरम परोसें।"]))
r.append(R(6536985,"न्यूट्रिशनल यीस्ट",
"4 बड़े चम्मच न्यूट्रिशनल यीस्ट की पोषण संबंधी जानकारी।",
"1","4 बड़े चम्मच",["4 बड़े चम्मच न्यूट्रिशनल यीस्ट"],[]))
r.append(R(6537876,"मलाईदार मसली हुई फूलगोभी",
"मलाईदार मसली हुई फूलगोभी तब एक कम कार्ब विकल्प है जब आपका मन मसले हुए आलू खाने का हो। मधुमेह के अनुकूल इस रेसिपी में वह सब कुछ है जो आप किसी क्लासिक आरामदायक व्यंजन से चाहेंगे।",
"4","3/4 कप",
["1 बड़ी फूलगोभी (फूलों में कटी हुई)","1 बड़ा चम्मच बिना नमक का मक्खन","2 कली लहसुन (बारीक कटी हुई)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट"],
["फूलगोभी के फूलों को तब तक भाप में पकाएँ या उबालें जब तक वे काँटे से आसानी से न धँसने लगें, लगभग 10–12 मिनट।","पकी हुई फूलगोभी को एक बड़े कटोरे में डालें।","एक छोटे पैन में मध्यम आँच पर मक्खन पिघलाएँ। कटा हुआ लहसुन डालें और खुशबू आने तक 1–2 मिनट भूनें।","लहसुन वाला मक्खन, नमक और काली मिर्च फूलगोभी में डालें।","फूलगोभी में ग्रीक योगर्ट डालें।","हैंड ब्लेंडर से फूलगोभी को चिकना और मलाईदार होने तक ब्लेंड करें।"]))
r.append(R(6538174,"मलाईदार चिकन सेब सलाद",
"यह सलाद कम कार्ब वाला, ताक़त से भरपूर आहार है। इसे बनाना आसान है और यह अच्छे पोषण से भरा है, जिसमें चिकन से प्रोटीन, सेब से फ़ाइबर और अखरोट से स्वस्थ वसा मिलती है। यह दोपहर के भोजन और पहले से तैयार करके रखने के लिए एकदम सही, एक तेज़ और मधुमेह के अनुकूल रेसिपी है। स्वाद और कुरकुरेपन से भरपूर, आपको यकीन नहीं होगा कि यह कितना आसान है!",
"8","1/2 कप",
["2 कप पका हुआ चिकन ब्रेस्ट (कटा हुआ)","2 डंठल अजवाइन (सेलरी) (टुकड़ों में कटे हुए)","2 हरे प्याज़ (कटे हुए)","1 मध्यम जोनागोल्ड सेब (बारीक टुकड़ों में कटा हुआ)","3 बड़े चम्मच अखरोट (कटे हुए)","1/4 कप लाइट मेयोनेज़","1/4 कप दही (सादा, फ़ैट-फ़्री)","1/2 नीबू (रस निकाला हुआ)","1/8 छोटा चम्मच काली मिर्च"],
["एक मध्यम कटोरे में चिकन, अजवाइन, हरे प्याज़, सेब और अखरोट को मिलाएँ।","एक छोटे कटोरे में मेयोनेज़, दही, नीबू का रस और काली मिर्च को फेंटकर मिलाएँ। इसे चिकन के मिश्रण पर डालें और धीरे से चलाकर लपेट दें।","सलाद को अपनी पसंद के लेट्यूस के पत्तों, ब्रेड या क्रैकर्स पर परोसें।"]))
r.append(R(6538918,"धनिया और नीबू के साथ शकरकंद का सलाद",
"यह टेक्स-मेक्स शैली का सलाद भरपेट और पेट भरने वाला है, और आपके स्वाद की कलियों को जगा देगा। यह मधुमेह के अनुकूल है और आपके अगले टैको मंगलवार के रात के खाने के लिए साइड डिश के रूप में बढ़िया रहेगा!",
"6","1 कप",
["2 बड़े शकरकंद (छिले हुए और निवाले के आकार के टुकड़ों में कटे हुए)","2 बड़े चम्मच जैतून का तेल","1 छोटा चम्मच जीरा","1/2 छोटा चम्मच स्मोक्ड पैपरिका","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप ताज़ा धनिया पत्ती (कटी हुई)","1 मध्यम नीबू (छिलका कसा हुआ और रस निकाला हुआ)","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","1 मध्यम एवोकाडो (टुकड़ों में कटा हुआ)","1 (15 औंस) डिब्बा काली बीन्स (कम सोडियम वाली, पानी निथारी और धुली हुई)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक बड़े कटोरे में कटे हुए शकरकंद को जैतून का तेल, जीरा, स्मोक्ड पैपरिका, नमक और काली मिर्च के साथ बराबर लिपटने तक मिलाएँ।","मसाले लगे शकरकंद को बेकिंग शीट पर एक परत में फैलाएँ।","पहले से गरम ओवन में 30 मिनट तक भूनें, या जब तक शकरकंद नरम और हल्के कैरामेलाइज़ न हो जाएँ, बीच में एक बार चलाएँ।","जब तक शकरकंद भुन रहे हों, ड्रेसिंग तैयार करें। नीबू का छिलका कसें और रस निकालें। एक छोटे कटोरे में कटी हुई ताज़ा धनिया पत्ती, नीबू का छिलका और नीबू का रस मिलाएँ।","शकरकंद के तैयार होने पर उन्हें परोसने वाले कटोरे में डालें।","धनिया और नीबू की ड्रेसिंग को भुने हुए शकरकंद पर डालें।","कटोरे में बारीक कटा लाल प्याज़, एवोकाडो और काली बीन्स डालें।","सलाद को धीरे से मिलाएँ ताकि ड्रेसिंग सब पर बराबर लग जाए।"]))
r.append(R(6538924,"फूलगोभी तब्बूलेह",
"तब्बूलेह स्वादिष्ट जड़ी-बूटियों, ताज़े नीबू और कूसकूस से बना एक पारंपरिक भूमध्यसागरीय सलाद है। मधुमेह के अनुकूल यह संस्करण कम कार्ब और अनाज-मुक्त विकल्प के लिए फूलगोभी के चावल का उपयोग करता है।",
"6","1 कप",
["1 कप कसकर भरी हुई अजमोद की पत्तियाँ","1/4 कप कसकर भरी हुई पुदीने की पत्तियाँ","1 छोटी फूलगोभी (या 16 औंस जमे हुए फूलगोभी के चावल) (पत्ते और डंठल हटाए हुए)","2 मध्यम रोमा (प्लम) टमाटर (बीज निकाले हुए और टुकड़ों में कटे हुए)","2 बड़े चम्मच जैतून का तेल","3 बड़े चम्मच नीबू का रस (ताज़ा निचोड़ा हुआ)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["अजमोद और पुदीने की पत्तियों को बारीक काटें (या फ़ूड प्रोसेसर में पीसें) और एक बड़े कटोरे में डालें।","फूलगोभी को बॉक्स ग्रेटर से कसें और अजमोद और पुदीने के साथ मिलाएँ।","कटे हुए टमाटर डालें और उन्हें सलाद में मिलाएँ।","सलाद पर जैतून का तेल और नीबू का रस डालें, और नमक (वैकल्पिक) और काली मिर्च छिड़कें। लपेटने के लिए मिलाएँ।","ढककर तब्बूलेह को परोसने से पहले 30 मिनट मैरिनेट होने दें।"]))
r.append(R(6539733,"आसान मध्य-पूर्वी हरी बीन्स",
"यह व्यंजन लूबिया नामक लेबनानी व्यंजन से प्रेरित है। यह बस हरी बीन्स और ग्रेप टमाटर हैं जिन्हें एक्स्ट्रा वर्जिन जैतून के तेल की ठीक सही मात्रा में पकाया जाता है और दालचीनी तथा समुद्री नमक से मसालेदार बनाया जाता है। यह जल्दी बन जाता है और आपके बाक़ी भोजन के पकने के दौरान आसानी से तैयार किया जा सकता है। इसे किसी सरल प्रोटीन व्यंजन, जैसे इस बाल्सैमिक ग्लेज़्ड सैल्मन, के साथ परोसें और हफ़्ते के दिनों के लिए एक तेज़ और आसान रात का खाना बनाएँ।\n\nयह रेसिपी और भी बहुत कुछ आपको The Clean & Simple Diabetes Cookbook में मिलेगा, जिसके लेखक Jackie Newgent, RDN, CDN हैं",
"2","1 1/2 कप",
["2 छोटे चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","8 औंस ताज़ी हरी बीन्स (डंठल वाले सिरे कटे हुए)","1 कप ग्रेप टमाटर","1/4 छोटा चम्मच पिसी दालचीनी","1/8 छोटा चम्मच नमक"],
["एक बड़ी नॉनस्टिक कड़ाही में मध्यम आँच पर तेल गरम करें। हरी बीन्स और टमाटर डालें, ढक दें, और तब तक पकाएँ जब तक हरी बीन्स नरम पर कुरकुरी न रहें और टमाटर पूरी तरह नरम न हो जाएँ, लगभग 10 मिनट। पकाने के दौरान चिमटे से दो-तीन बार उछालकर मिलाएँ।","सब्ज़ियों पर दालचीनी और नमक छिड़कें। मिलाने के लिए उछालें, फिर परोसें।"]))
r.append(R(6540545,"साबुत गेहूँ के पालक पराठे",
"पराठा एक प्रकार की रोटी है जो भारत के उत्तरी हिस्से में शुरू हुई, जहाँ यह आज भी लोकप्रिय है। यह पारंपरिक भारतीय नाश्ते का हिस्सा है, लेकिन इसे दोपहर या रात के खाने के साथ भी परोसा जा सकता है।",
"8","1 पराठा",
["2/3 कप पानी","2 कप और 1 बड़ा चम्मच साबुत गेहूँ का पेस्ट्री आटा (बाँटा हुआ)","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच अमचूर (आम) पाउडर","1/2 छोटा चम्मच बारीक समुद्री नमक (बाँटकर उपयोग)","1 कप (कसकर भरा हुआ) बेबी पालक (कटा हुआ)","1 साबुत हरी मिर्च (बीज निकाले हुए, बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा अदरक (कसा हुआ)","1 छोटा चम्मच अजवाइन के बीज","3 छोटे चम्मच सूरजमुखी का तेल (बाँटकर उपयोग)"],
["एक भारी तले वाले पैन में मध्यम-तेज़ आँच पर 1 छोटा चम्मच तेल गरम करें। अजवाइन के बीज, अदरक और हरी मिर्च डालें। बार-बार चलाते हुए लगभग 1 मिनट पकाएँ।","पालक और ¼ छोटा चम्मच नमक डालें। 3 मिनट पकाएँ, या जब तक पालक से निकली नमी सूख न जाए और मिश्रण सूखा न हो जाए। अमचूर पाउडर और जीरा डालकर अच्छी तरह मिलाएँ। आँच से उतार लें। ठंडा होने के लिए अलग रख दें।","पराठे का आटा गूँधने के लिए: एक चौड़े बर्तन में 2 कप आटा और बचा हुआ ¼ छोटा चम्मच नमक मिलाएँ। पालक का मिश्रण आटे के मिश्रण में डालें। थोड़ा-थोड़ा पानी डालकर चिकना आटा गूँधें (पिज़्ज़ा के आटे जैसी consistency)। आटे को चिकना होने तक गूँधें। इसे काँच के कटोरे में डालें। गीले तौलिये से ढकें। कमरे के तापमान पर 30 मिनट से एक घंटे के लिए अलग रख दें।","आटा रखने के बाद उसे एक बार फिर गूँधें। 8 लोइयाँ बनाएँ। अपनी काम की सतह पर बचा हुआ 1 बड़ा चम्मच आटा हल्के से बुरकें। बेलन से हर लोई को 6 इंच व्यास तक बेलकर चपटा करें।","एक कास्ट आयरन तवे या चपटी कड़ाही को मध्यम-तेज़ आँच पर पहले से गरम करें। आटे का एक टुकड़ा तवे पर रखें। लगभग 1 मिनट पकाएँ, या जब तक उसमें बुलबुले न उठने लगें।","पराठे को पलटें। बचे हुए तेल में से ¼ छोटा चम्मच तेल लगाएँ। ज़रूरत के अनुसार पलटते हुए हर तरफ़ लगभग 3–4 मिनट पकाना जारी रखें, जब तक दोनों तरफ़ किनारे भूरे न हो जाएँ। पकते समय चपटे स्पैचुला से पराठे के बीच के हिस्से को दबाएँ ताकि वह बराबर पके।","तवे से उतारें। आटे के बाक़ी टुकड़ों और बचे हुए तेल के साथ यही पकाने की प्रक्रिया दोहराएँ। गरम परोसें।"]))
r.append(R(6541626,"कैप्रेसे कबाब",
"यह आसान स्टार्टर गर्मियों के लिए एकदम सही है और बगीचे की ताज़ा सामग्री का उपयोग करता है। ये कबाब स्वाद से भरपूर और कार्बोहाइड्रेट में कम हैं। ये परोसने की प्लैटर पर भी बहुत सुंदर लगते हैं और मेहमानों को निश्चित रूप से प्रभावित करेंगे!",
"18","1 कबाब",
["18 छोटी बाँस की सींकें","18 पत्ते ताज़ी तुलसी (आधे मोड़े हुए)","18 मध्यम ग्रेप टमाटर","18 साबुत ताज़ी मोज़ेरेला गेंदें (प्रत्येक 1/4 औंस)","1 बड़ा चम्मच जैतून का तेल","1 1/2 बड़े चम्मच बाल्सैमिक सिरका"],
["हर बाँस की सींक पर 1 ग्रेप टमाटर, 1 तुलसी का पत्ता और 1 मोज़ेरेला गेंद लगाएँ। 18 कबाब के लिए यह प्रक्रिया दोहराएँ। कबाब को परोसने की प्लैटर पर रखें।","एक छोटे कटोरे में जैतून का तेल और बाल्सैमिक सिरका फेंटकर मिलाएँ। परोसने से ठीक पहले ड्रेसिंग को कबाब पर बराबर डालें।"]))
r.append(R(6541800,"ब्लड ऑरेंज सलाद (इंसालाटा द'अरांचे सांगुइने)",
"सिसिली अपने सुंदर, हरे-भरे संतरे के बागों के लिए जाना जाता है, जो दुनिया के कुछ सबसे सुगंधित संतरे पैदा करते हैं। अरबों ने द्वीप पर अपने शासन के दौरान इन्हें पहली बार शुरू किया था, और संतरे के पेड़ माउंट एटना की तलहटी की राख में फले-फूले। इस रेसिपी के लिए सबसे मीठे संतरे ढूँढें। यदि हो सके तो सिसिली के ब्लड ऑरेंज का उपयोग करें; उनका लाल रंग इस शानदार सलाद को उत्सव जैसा आकर्षण देता है।",
"6","1/2 कप",
["4 साबुत ब्लड ऑरेंज (कुल लगभग 1 पाउंड, छिले हुए और गोल स्लाइस में कटे हुए)","2 डंठल हरा प्याज़ (स्कैलियन) (बारीक कटे हुए)","1/4 कप 1 संतरे का रस","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (अधिमानतः पहली कोल्ड-प्रेस्ड और बिना छना)","1/4 छोटा चम्मच अपरिष्कृत समुद्री नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई)","1/8 छोटा चम्मच कुटी हुई लाल मिर्च के फ़्लेक्स"],
["संतरे के स्लाइस को एक बड़ी प्लैटर पर रखें और ऊपर हरे प्याज़ बिखेर दें।","एक छोटे कटोरे में संतरे का रस और जैतून का तेल फेंटकर मिलाएँ, और नमक, काली मिर्च और कुटी हुई लाल मिर्च के फ़्लेक्स से स्वाद बनाएँ। इसे सलाद पर डालें और तुरंत परोसें।"]))
r.append(R(6543489,"व्हिप्ड कॉटेज चीज़ डिप",
"व्हिप्ड कॉटेज चीज़ डिप पारंपरिक डिप का हल्का और मलाईदार विकल्प है, जो स्नैकिंग के लिए प्रोटीन से भरपूर विकल्प देता है। इसका आनंद अपनी पसंदीदा सब्ज़ियों, जैसे ब्रोकली, शिमला मिर्च, गाजर और अन्य के साथ लें!",
"4","1/3 कप",
["1 कप कॉटेज चीज़ (कम चर्बी वाला)","2 बड़े चम्मच सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 बड़ा चम्मच नीबू का रस","2 छोटे चम्मच वूस्टरशायर सॉस","1 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा चाइव्स (कटी हुई)","1/4 छोटा चम्मच काली मिर्च"],
["ब्लेंडर या फ़ूड प्रोसेसर में कम चर्बी वाला कॉटेज चीज़, ग्रीक योगर्ट, ताज़ा नीबू का रस, वूस्टरशायर सॉस और कटा हुआ लहसुन मिलाएँ। सामग्री को तब तक ब्लेंड करें जब तक मिश्रण चिकना और मलाईदार न हो जाए। आपके ब्लेंडर या फ़ूड प्रोसेसर की शक्ति के अनुसार इसमें कुछ मिनट लग सकते हैं।","मिश्रण के चिकना होने पर उसे एक कटोरे में निकालें। कटी हुई ताज़ा चाइव्स मिलाएँ और व्हिप्ड कॉटेज चीज़ डिप में काली मिर्च डालें। अच्छी तरह मिलाएँ ताकि स्वाद बराबर फैल जाए।","परोसने से पहले डिप को कम से कम 30 मिनट रेफ़्रिजरेटर में रखें ताकि स्वाद आपस में घुल-मिल जाएँ और समग्र स्वाद बेहतर हो।"]))
r.append(R(6545397,"बीफ़ स्ट्रोगनॉफ़",
"एक भरपेट और स्वादिष्ट व्यंजन तैयार करें जो आपकी चाहत को संतुष्ट करेगा और साथ ही आपके रक्त ग्लूकोज़ (ब्लड शुगर) के स्तर को नियंत्रण में रखने में मदद करेगा। कम चर्बी वाले बीफ़ और सेहतमंद सामग्री के साथ मलाईदार, स्वादिष्ट सॉस बनाना चरण-दर-चरण सीखें, जो इस व्यंजन को स्वादिष्ट और आपकी सेहत का ध्यान रखने वाला दोनों बनाता है। चाहे आप अपने लिए पका रहे हों या अपने प्रियजनों के लिए, यह रेसिपी आपकी रसोई का मुख्य व्यंजन बन जाएगी।",
"5","रेसिपी का 1/5 भाग",
["5 औंस साबुत अनाज के एग नूडल्स (बिना पके)","1 छोटा चम्मच जैतून का तेल","1 पाउंड बीफ़ टेंडरलॉइन (0\" ट्रिम, 2 इंच की पट्टियों में कटा हुआ)","1 1/2 कप सफ़ेद (बटन) मशरूम (स्लाइस किए हुए)","1/2 मध्यम प्याज़ (बारीक कटा हुआ)","1 बड़ा चम्मच मैदा (ऑल-पर्पज़ आटा)","1/4 कप पानी","1 छोटा चम्मच डिजॉन मस्टर्ड","14 1/2 औंस फ़ैट-फ़्री, बिना नमक मिलाया बीफ़ ब्रॉथ","1/2 कप फ़ैट-फ़्री सावर क्रीम","1/4 छोटा चम्मच काली मिर्च"],
["पैकेट पर दिए निर्देशों के अनुसार नूडल्स पकाएँ, नमक न डालें।","एक बड़े सॉते पैन में तेज़ आँच पर तेल डालें। मांस डालें और लगभग 3 मिनट भूनें। मांस को पैन से निकाल लें। मशरूम और प्याज़ डालें और 5 मिनट या भूरा होना शुरू होने तक भूनें।","आटा डालें और 1 मिनट पकाएँ। पैन को डीग्लेज़ करने के लिए धीरे से पानी डालें; 2 मिनट पकाएँ। डिजॉन मस्टर्ड और बीफ़ ब्रॉथ डालें; उबाल आने दें। आँच कम करें और 5 मिनट धीमी आँच पर पकाएँ।","बीफ़ और उसका रस वापस ब्रॉथ में डालें और 3 मिनट और धीमी आँच पर पकाएँ। सावर क्रीम और काली मिर्च डालें; 30 सेकंड धीमी आँच पर पकाएँ।","साबुत अनाज के एग नूडल्स के ऊपर परोसें।"]))
